namespace VisionFramework;
public static class WorkflowRunParameters{
 public static void Validate(WorkflowConfiguration c,ProcedureDocument p,ModuleRegistry? registry){
  var limit=WorkflowRunParameterLimit.Current;var categories=c.RunCategories??[];if(categories.Count>limit||c.RunParameters.Count>limit||categories.Select(g=>g.Id).Distinct().Count()!=categories.Count||categories.Select(g=>g.Name).Distinct().Count()!=categories.Count)throw new InvalidDataException("Invalid run parameter categories/count.");foreach(var g in categories){if(string.IsNullOrWhiteSpace(g.Id))throw new InvalidDataException("Missing category identity.");WorkflowConfiguration.CheckName(g.Name);}
  if(p.GroupOwner is not null&&(c.RunParameters.Any(r=>string.IsNullOrWhiteSpace(r.Label))||c.RunParameters.Select(r=>r.Label).Distinct().Count()!=c.RunParameters.Count))throw new InvalidDataException("Missing or duplicate runtime parameter name.");foreach(var proxy in c.RunParameters){if(proxy.CategoryId is {} id&&!categories.Any(g=>g.Id==id))throw new InvalidDataException("Missing runtime category.");var targets=proxy.Targets().ToArray();if(targets.Length>128||targets.Distinct().Count()!=targets.Length)throw new InvalidDataException("Duplicate/excessive runtime relations.");ParameterDescriptor? first=null;PortDescriptor? input=null;foreach(var t in targets){var n=p.Nodes.SingleOrDefault(n=>n.Id==t.NodeId)??throw new InvalidDataException("Missing runtime relation node.");if(t.IsInput!=proxy.IsInput)throw new InvalidDataException("Cannot mix input and parameter relations.");if(registry is null)continue;var d=registry.GetDescriptor(n);if(t.IsInput){var spec=d.Inputs.SingleOrDefault(s=>s.Name==t.Parameter)??throw new InvalidDataException("Missing related input.");if(input is not null&&(input.Kind!=spec.Kind||input.Cardinality!=spec.Cardinality))throw new InvalidDataException("Related input types differ.");input=spec;}else{var spec=d.Parameters.SingleOrDefault(s=>s.Name==t.Parameter)??throw new InvalidDataException("Missing related parameter.");if(first is not null&&first.Kind!=spec.Kind)throw new InvalidDataException("Related parameter types differ.");if(first is not null&&(first.Editor?.Kind!=spec.Editor?.Kind||!(first.Editor?.Fields??[]).SequenceEqual(spec.Editor?.Fields??[])))throw new InvalidDataException("Related complex editors differ.");if(first?.Editor?.Roi is {} a&&spec.Editor?.Roi is {} b&&(a.Maximum!=b.Maximum||a.PolygonPointMaximum!=b.PolygonPointMaximum||a.FullImage!=b.FullImage||a.Exclusions!=b.Exclusions||!a.Kinds.SequenceEqual(b.Kinds)))throw new InvalidDataException("Related ROI capabilities differ.");first=spec;}}
  }
 }
}
